import express from "express";
import cors from "cors";
import { PrismaClient } from "@prisma/client";
import { auditPlansRouter } from "./routes/auditPlans";
import { auditsRouter } from "./routes/audits";
import { checklistRouter } from "./routes/checklist";
import { evidenceRouter } from "./routes/evidence";
import { findingsRouter } from "./routes/findings";
import { correctiveActionsRouter } from "./routes/correctiveActions";
import { dashboardRouter } from "./routes/dashboard";
import { referenceRouter } from "./routes/reference";
import { errorHandler } from "./middleware/errorHandler";
export const prisma = new PrismaClient();
const app = express();
const PORT = process.env.PORT || 5002;
app.use(cors());
app.use(express.json());
app.use("/api/audit/plans", auditPlansRouter);
app.use("/api/audit/audits", auditsRouter);
app.use("/api/audit/checklist", checklistRouter);
app.use("/api/audit/evidence", evidenceRouter);
app.use("/api/audit/findings", findingsRouter);
app.use("/api/audit/corrective-actions", correctiveActionsRouter);
app.use("/api/audit/dashboard", dashboardRouter);
app.use("/api/audit/reference", referenceRouter);
app.get("/api/audit/health", (req, res) => res.json({ ok: true }));
app.use(errorHandler);
app.listen(PORT, () => {
    console.log(`[WADJET Audit] API running on http://localhost:${PORT}`);
});
